'use strict';

// Convierte el correo del nodo IMAP (o del webhook de prueba) en texto limpio.
// El HTML, la firma y la cadena de respuestas no deben llegar al modelo.

const crypto = require('crypto');

// Acentos rotos del nodo IMAP de n8n 2.10.2 en formato "simple". @n8n/imap
// decodifica el quoted-printable sin pasarle el charset de la parte
// (getPartData llama a PartData.fromData sin él), así que un cuerpo UTF-8 de
// Gmail llega con cada byte leído como latin1: "producciÃ³n", "Â¿cuÃ¡l". El
// asunto llega bien porque va por la cabecera (RFC 2047).
// Se repara solo si tiene pinta de eso, todo el texto cabe en latin1 y la vuelta
// es UTF-8 válido. Un texto correcto ("producción", "São Paulo", emojis) no se toca.
const MOJIBAKE = /[\u00C2-\u00F4][\u0080-\u00BF]/;

// UTF-8 a mano, por si el runner no tuviera Buffer (en n8n 2.10.2 sí lo tiene).
// Cada carácter del texto es un byte. Devuelve null si no es UTF-8 válido.
function decodeUtf8Bytes(text) {
  let out = '';
  for (let i = 0; i < text.length;) {
    const lead = text.charCodeAt(i);
    if (lead < 0x80) {
      out += text[i];
      i += 1;
      continue;
    }
    const size = lead >= 0xC2 && lead <= 0xDF ? 2 : lead >= 0xE0 && lead <= 0xEF ? 3 : lead >= 0xF0 && lead <= 0xF4 ? 4 : 0;
    if (!size || i + size > text.length) return null;
    let code = lead & (size === 2 ? 0x1F : size === 3 ? 0x0F : 0x07);
    for (let k = 1; k < size; k += 1) {
      const next = text.charCodeAt(i + k);
      if ((next & 0xC0) !== 0x80) return null;
      code = (code << 6) | (next & 0x3F);
    }
    if (size === 3 && (code < 0x800 || (code >= 0xD800 && code <= 0xDFFF))) return null;
    if (size === 4 && (code < 0x10000 || code > 0x10FFFF)) return null;
    out += String.fromCodePoint(code);
    i += size;
  }
  return out;
}

// charset de la cabecera Content-Type del correo, solo si es una parte de texto.
// En un multipart (lo normal en Gmail) el charset va en cada parte y aquí no está.
function declaredCharset(headers) {
  const type = String((headers && headers['content-type']) || '');
  if (!/^\s*text\//i.test(type)) return '';
  const match = type.match(/charset\s*=\s*"?([^";\s]+)/i);
  return match ? match[1].toLowerCase() : '';
}

function repairMojibake(value, charset = '') {
  const text = String(value ?? '');
  if (!MOJIBAKE.test(text)) return text;
  // El correo dice que no es UTF-8: lo que llega no es UTF-8 mal leído.
  if (charset && !/^utf-?8$/.test(charset)) return text;
  if (/[^\u0000-\u00FF]/.test(text)) return text;
  const fixed = typeof Buffer === 'function'
    ? Buffer.from(text, 'latin1').toString('utf8')
    : decodeUtf8Bytes(text);
  // Buffer cambia lo inválido por U+FFFD; el texto de entrada no puede traerlo (es latin1).
  if (fixed === null || fixed.includes('\uFFFD')) return text;
  return fixed;
}

function decodeEntities(value) {
  return String(value || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
}

function htmlToText(html) {
  let text = String(html || '');
  text = text.replace(/<script[\s\S]*?<\/script>/gi, ' ');
  text = text.replace(/<style[\s\S]*?<\/style>/gi, ' ');
  text = text.replace(/<img\b[^>]*>/gi, ' ');
  text = text.replace(/<br\s*\/?>/gi, '\n');
  text = text.replace(/<\/p>/gi, '\n');
  text = text.replace(/<\/div>/gi, '\n');
  text = text.replace(/<\/tr>/gi, '\n');
  text = text.replace(/<[^>]+>/g, ' ');
  return decodeEntities(text);
}

// El nodo IMAP en formato "simple" deja las cabeceras en metadata como
// "valor". En formato "resolved" llegan en headers como "Clave: valor".
// Aquí se queda solo el valor, con la clave en minúsculas.
function headerMap(raw) {
  const metadata = raw.metadata && typeof raw.metadata === 'object' ? raw.metadata : {};
  const headers = raw.headers && typeof raw.headers === 'object' ? raw.headers : {};
  const merged = {};
  for (const [key, value] of Object.entries({ ...metadata, ...headers })) {
    const name = String(key).toLowerCase();
    let text = Array.isArray(value) ? value.join(' ') : String(value ?? '');
    const prefix = name + ':';
    if (text.toLowerCase().startsWith(prefix)) text = text.slice(prefix.length);
    merged[name] = text.replace(/\s+/g, ' ').trim();
  }
  return merged;
}

function isoOrNull(value) {
  const time = Date.parse(value || '');
  if (!Number.isFinite(time)) return null;
  return new Date(time).toISOString();
}

function parseAddress(value) {
  // Formato "resolved" de mailparser: { value: [{ address, name }], text }.
  if (value && typeof value === 'object') {
    const first = Array.isArray(value.value) ? value.value[0] : null;
    if (first && first.address) return { address: String(first.address).trim().toLowerCase(), name: String(first.name || '').trim() };
    value = value.text || '';
  }
  const text = String(value || '').replace(/[\r\n]+/g, ' ').trim();
  const match = text.match(/<([^>]+)>/);
  const address = (match ? match[1] : text).trim().toLowerCase();
  const name = match ? text.slice(0, match.index).replace(/"/g, '').trim() : '';
  return { address, name };
}

function cutQuotedChain(text) {
  const markers = [
    /^-----Original Message-----/im,
    /^_{5,}\s*$/m,
    /^On .+wrote:\s*$/im,
    /^El .+escribi[oó]:\s*$/im,
    /^From:\s.+\nSent:\s/im,
    /^De:\s.+\nEnviado(?: el)?:\s/im,
    /^>+ ?On .+wrote:\s*$/im,
  ];
  let cut = text.length;
  for (const marker of markers) {
    const found = marker.exec(text);
    if (found && found.index < cut) cut = found.index;
  }
  const kept = text.slice(0, cut);
  return kept
    .split('\n')
    .filter((line) => !/^\s*>/.test(line))
    .join('\n');
}

function cutSignature(text) {
  const lines = text.split('\n');
  const cutAt = lines.findIndex((line) => {
    const trimmed = line.trim();
    return trimmed === '--' || trimmed === '—' || /^enviado desde mi /i.test(trimmed) || /^sent from my /i.test(trimmed) || /^get outlook for /i.test(trimmed);
  });
  if (cutAt <= 0) return text;
  return lines.slice(0, cutAt).join('\n');
}

function stripTrackers(text) {
  return text.replace(/https?:\/\/[^\s>]+/gi, (url) => {
    try {
      const parsed = new URL(url);
      for (const key of [...parsed.searchParams.keys()]) {
        if (/^(utm_|mc_|mkt_|fbclid|gclid|vero_)/i.test(key)) parsed.searchParams.delete(key);
      }
      if (/pixel|track|open\.gif|spacer/i.test(parsed.pathname)) return '';
      return parsed.toString();
    } catch {
      return url;
    }
  });
}

function sha256(text) {
  return crypto.createHash('sha256').update(String(text)).digest('hex');
}

// Clave de idempotencia. Si el correo trae Message-ID, es ese. Si no lo trae,
// se calcula con remitente, destinatario, fecha, asunto y cuerpo: el mismo
// correo leído dos veces da la misma clave y no se procesa dos veces.
// Un Message-ID absurdo de largo se resume para que el índice único no falle.
function messageKey(rawId, mail) {
  const id = String(rawId || '').replace(/\s+/g, '').replace(/^<|>$/g, '');
  if (id && id.length <= 400) return { message_id: id, message_id_generated: false };
  if (id) return { message_id: 'largo-' + sha256(id).slice(0, 40), message_id_generated: true };
  const seed = [mail.from_address, mail.to_address, mail.received_at || '', mail.subject, mail.body].join('\n');
  return { message_id: 'generado-' + sha256(seed).slice(0, 40), message_id_generated: true };
}

function normalizeEmail(raw) {
  const source = raw && raw.body && typeof raw.body === 'object' && (raw.body.text || raw.body.textPlain || raw.body.subject || raw.body.from)
    ? raw.body
    : (raw || {});
  const headers = headerMap(source);
  // Lo primero: los acentos. Todo lo demás (HTML, firma, citas) ya trabaja con texto bueno.
  const charset = declaredCharset(headers);
  const plain = repairMojibake(source.textPlain || source.text || (typeof source.body === 'string' ? source.body : '') || '', charset).trim();
  const html = repairMojibake(source.textHtml || (typeof source.html === 'string' ? source.html : '') || '', charset).trim();
  let body = plain || htmlToText(html);
  body = body.replace(/\r\n/g, '\n').replace(/ /g, ' ');
  body = cutQuotedChain(body);
  body = cutSignature(body);
  body = stripTrackers(body);
  body = body.replace(/[ \t]+\n/g, '\n').replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  if (body.length > 8000) body = body.slice(0, 8000);

  const from = parseAddress(source.from || headers.from || '');
  const to = parseAddress(source.to || headers.to || '');
  const mail = {
    from_address: from.address,
    from_name: from.name.slice(0, 200),
    to_address: to.address,
    subject: String(source.subject || headers.subject || '').replace(/\s+/g, ' ').trim().slice(0, 500),
    body,
    in_reply_to: String(headers['in-reply-to'] || source.inReplyTo || '').trim().slice(0, 1000),
    references_header: String(headers.references || (Array.isArray(source.references) ? source.references.join(' ') : source.references) || '').trim().slice(0, 4000),
    headers,
    received_at: isoOrNull(source.date || headers.date),
  };
  const key = messageKey(headers['message-id'] || source.messageId || source.message_id, mail);
  return { message_id: key.message_id, message_id_generated: key.message_id_generated, ...mail };
}

return { json: normalizeEmail($json) };

'use strict';

// El cuerpo de un correo es texto de un desconocido. Estas reglas cortan
// autorespuestas y marcan intentos de inyección antes de gastar el modelo.

const INJECTION_PATTERNS = [
  /ignora (tus |las |todas las )?(instrucciones|reglas)/i,
  /ignore (all |any )?(previous|prior|above) instructions/i,
  /disregard (all |any )?(previous|prior|above) instructions/i,
  /olvida (las |tus |todas las )?(reglas|instrucciones)/i,
  /system prompt/i,
  /you are now/i,
  /eres (ahora )?(otro|un nuevo) asistente/i,
  /act[uú]a como si no tuvieras/i,
  /responde que (le |nos )?devolvemos el dinero/i,
  // Intento de cerrar el bloque de datos y escribir fuera de él.
  /<\s*\/?\s*(correo_no_confiable|fuentes_rag|system|assistant)\b/i,
];

// Una sola dirección, sin comas ni espacios. Si el From trae dos direcciones
// o algo raro, no se contesta: la respuesta podría salir a un tercero.
const ADDRESS = /^[^\s@,;:<>()[\]"'\\]+@[^\s@,;:<>()[\]"'\\]+\.[^\s@,;:<>()[\]"'\\]+$/;

function isValidAddress(address) {
  const value = String(address || '');
  return value.length <= 254 && ADDRESS.test(value);
}

function looksLikeNoReply(address) {
  const value = String(address || '').toLowerCase();
  return /(^|[^a-z])(no-?reply|mailer-daemon|postmaster)@/.test(value);
}

function inspectMail(mail, supportAddress) {
  const headers = mail.headers || {};
  const autoSubmitted = String(headers['auto-submitted'] || '').toLowerCase();
  const reasons = [];
  if (autoSubmitted && autoSubmitted !== 'no') reasons.push('auto-submitted');
  if (headers['x-autoreply'] || headers['x-autorespond'] || headers['x-auto-response-suppress']) {
    reasons.push('x-autoreply');
  }
  if (headers['list-id']) reasons.push('list-id');
  const precedence = String(headers.precedence || '').toLowerCase();
  if (['bulk', 'list', 'junk', 'auto_reply'].includes(precedence)) reasons.push('precedence');
  if (!isValidAddress(mail.from_address)) reasons.push('remitente-invalido');
  if (looksLikeNoReply(mail.from_address)) reasons.push('no-reply');
  if (supportAddress && mail.from_address === String(supportAddress).toLowerCase()) reasons.push('propio');

  const blob = `${mail.subject}\n${mail.body}`;
  const injection = INJECTION_PATTERNS.some((pattern) => pattern.test(blob));
  return {
    ignore: reasons.length > 0,
    ignore_reason: reasons.join(','),
    injection,
  };
}

const config = $('Configuración').first().json;
const verdict = inspectMail($json, config.support_address);
return { json: { ...$json, ...verdict } };

const email = $('Con reserva').item.json;
let parsed = [];
const raw = $json.rag_raw || $json.data || '';
if (!$json.error && raw) {
  try { parsed = JSON.parse(raw); } catch (error) { parsed = []; }
}
if (parsed && parsed.error) parsed = [];
if (!Array.isArray(parsed)) parsed = [];
const sources = parsed.slice(0, 5).map((row) => ({
  document_id: row.document_id || null,
  title: String(row.title || '').slice(0, 300),
  canonical_url: String(row.canonical_url || '').slice(0, 500),
  score: Number(row.score || 0),
  content: String(row.content || '').slice(0, 700),
  source_type: row.source_type || '',
  chunk_index: row.chunk_index,
})).sort((a, b) => b.score - a.score);
const ids = sources.map((row) => row.document_id).filter((id) => /^[0-9a-f-]{36}$/i.test(String(id)));
return { json: { ...email, sources, source_ids: ids.join(',') } };

const email = $('Unir fuentes').item.json;
const pairs = String($json.pairs || '').split(',').filter(Boolean);
const dates = {};
for (const pair of pairs) {
  const cut = pair.indexOf('|');
  if (cut > 0) dates[pair.slice(0, cut)] = pair.slice(cut + 1);
}
const sources = (email.sources || []).map((source) => ({ ...source, updated_at: dates[source.document_id] || null }));
return { json: { ...email, sources } };

'use strict';

// Mensaje de usuario para el modelo. Las instrucciones van en el prompt de
// sistema (prompts/clasificador.md). Aquí solo hay datos, entre marcas.
// Si el correo o una fuente traen las propias marcas, se borran: así nadie
// puede cerrar el bloque <correo_no_confiable> y escribir fuera de él.

const DATA_TAGS = /<\s*\/?\s*(correo_no_confiable|fuentes_rag)\b[^>]*>/gi;

function neutralize(value) {
  return String(value ?? '').replace(DATA_TAGS, '[marca eliminada]');
}

function buildUserBlock(email, sources) {
  const list = Array.isArray(sources) ? sources : [];
  const packed = list.map((source, index) => (
    '[' + (index + 1) + '] ' + neutralize(source.title) + ' | ' + (source.updated_at || 'sin fecha') + ' | ' + neutralize(source.canonical_url) + '\n' + neutralize(source.content)
  )).join('\n\n');
  return [
    '<correo_no_confiable>',
    'asunto: ' + neutralize(email.subject),
    'de: ' + neutralize(email.from_address),
    'cuerpo:',
    neutralize(email.body),
    '</correo_no_confiable>',
    '<fuentes_rag>',
    packed || '(sin fragmentos)',
    '</fuentes_rag>',
  ].join('\n');
}

const email = $json.sources ? $json : $('Unir fuentes').item.json;
return { json: { ...email, user_block: buildUserBlock(email, email.sources || []) } };

'use strict';

// La decisión final no se fía del modelo. Si el JSON no parsea, si huele a
// inyección o si el tema tiene consecuencias, no se responde solo.
// Un correo bloqueado (inyección o promesa de dinero) se queda SIN borrador:
// en Telegram no hay botón Aprobar y solo sale lo que escriba una persona.

const CATEGORIES = ['consulta_frecuente', 'bug', 'incidencia_urgente', 'lead', 'spam', 'revision'];

const GRANT_PATTERNS = [
  /te devolvemos/i,
  /le devolvemos el dinero/i,
  /reembolso aprobado/i,
  /hemos abonado/i,
  /refund approved/i,
  /we will refund/i,
  /full refund/i,
];

function clamp(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.min(1, Math.max(0, number));
}

function extractJson(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(raw.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

function llmPayload(response) {
  if (!response) return '';
  if (typeof response === 'string') return response;
  const content = response.choices && response.choices[0] && response.choices[0].message
    ? response.choices[0].message.content
    : response.content;
  return typeof content === 'string' ? content : JSON.stringify(response);
}

// Trozos del prompt o de las marcas de datos en el borrador: el modelo está
// repitiendo instrucciones o el correo intentó sacarlas. No se envía.
const LEAK_PATTERNS = [
  /correo_no_confiable/i,
  /fuentes_rag/i,
  /eres el clasificador de soporte/i,
  /esquema exacto/i,
];

const MAX_DRAFT = 4000;

// Valida la forma del JSON del modelo. Devuelve null si no es un objeto con
// una categoría en texto y una confianza numérica: eso cuenta como JSON roto.
function validateModelOutput(parsed) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  if (typeof parsed.categoria !== 'string') return null;
  const confidence = Number(parsed.confianza);
  if (parsed.confianza === null || parsed.confianza === '' || !Number.isFinite(confidence)) return null;
  const text = (value) => (typeof value === 'string' ? value.trim() : '');
  return {
    categoria: CATEGORIES.includes(parsed.categoria.trim()) ? parsed.categoria.trim() : 'revision',
    confianza: clamp(confidence),
    borrador: text(parsed.borrador_respuesta).slice(0, MAX_DRAFT),
    razonamiento: text(parsed.razonamiento).slice(0, 1000),
  };
}

function leaksPrompt(draft) {
  return LEAK_PATTERNS.some((pattern) => pattern.test(String(draft || '')));
}

function isSensitive(text, topics) {
  const haystack = String(text || '').toLowerCase();
  return topics.some((topic) => topic && haystack.includes(String(topic).toLowerCase()));
}

function coversQuestion(body, sources) {
  const normalize = (value) => String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const tokens = normalize(body).split(/[^a-z0-9]+/).filter((word) => word.length > 4);
  if (tokens.length === 0) return false;
  const blob = normalize((sources || []).slice(0, 2).map((source) => `${source.title || ''} ${source.content || ''}`).join(' '));
  const hits = tokens.filter((word) => blob.includes(word));
  return hits.length >= 2 || (hits.length === 1 && tokens.length <= 3);
}

function sourcesAllowGrant(sources) {
  const blob = (sources || []).map((source) => `${source.title || ''}\n${source.content || ''}`).join('\n');
  return /reembolso íntegro|devolución del dinero/i.test(blob);
}

function outputGrantsMoney(draft, sources) {
  if (sourcesAllowGrant(sources)) return false;
  return GRANT_PATTERNS.some((pattern) => pattern.test(String(draft || '')));
}

function decide(input, config) {
  const threshold = Number(config.confidence_threshold ?? 0.75);
  const minScore = Number(config.min_rag_score ?? 0.45);
  const topics = String(config.sensitive_topics || '')
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
  const sources = Array.isArray(input.sources) ? input.sources : [];
  const parsed = validateModelOutput(input.parsed);
  const topScore = Number(sources[0] && sources[0].score) || 0;

  if (!parsed) {
    return {
      category: 'revision',
      confidence: 0,
      draft_reply: '',
      reasoning: 'El modelo no devolvió JSON válido. Pasa a una persona.',
      route: 'approval',
      status: 'revision_humana',
      sensitive: false,
      injection: Boolean(input.injection),
      blocked: false,
    };
  }

  const category = parsed.categoria;
  let confidence = parsed.confianza;
  const draft = parsed.borrador;
  const reasoning = parsed.razonamiento;
  const sensitive = isSensitive(`${input.subject}\n${input.body}\n${draft}`, topics);
  const grants = outputGrantsMoney(draft, sources);
  const leak = leaksPrompt(draft);
  const injection = Boolean(input.injection);

  if (injection || grants || leak) {
    const why = injection
      ? 'El correo intenta dar instrucciones al sistema.'
      : grants
        ? 'El borrador prometía una devolución que no está en la base de conocimiento.'
        : 'El borrador repetía instrucciones internas.';
    // El borrador del modelo se tira: pudo escribirlo el atacante. Lo que vea
    // el remitente lo escribirá una persona con el botón Editar.
    return {
      category: 'revision',
      confidence: Math.min(confidence, 0.2),
      draft_reply: '',
      reasoning: (why + ' No hay borrador: responde con Editar o rechaza. ' + reasoning).trim().slice(0, 1000),
      route: 'approval',
      status: 'esperando_aprobacion',
      sensitive,
      injection: true,
      blocked: true,
    };
  }

  if (category === 'spam') {
    return { category, confidence, draft_reply: '', reasoning, route: 'spam', status: 'descartado', sensitive, injection: false, blocked: false };
  }
  if (category === 'bug') {
    return { category, confidence, draft_reply: draft, reasoning, route: 'bug', status: 'pendiente', sensitive, injection: false, blocked: false };
  }
  if (category === 'incidencia_urgente') {
    return { category, confidence, draft_reply: draft, reasoning, route: 'urgent', status: 'pendiente', sensitive, injection: false, blocked: false };
  }
  if (category === 'lead') {
    return { category, confidence, draft_reply: draft, reasoning, route: 'lead', status: 'pendiente', sensitive, injection: false, blocked: false };
  }

  const vague = String(input.body || '').trim().length < 40;
  if (vague) confidence = Math.min(confidence, 0.55);

  if (!draft || sensitive || category !== 'consulta_frecuente' || confidence < threshold || topScore < minScore || sources.length === 0 || !coversQuestion(input.body, sources)) {
    return {
      category: category === 'consulta_frecuente' ? category : 'revision',
      confidence,
      draft_reply: draft,
      reasoning,
      route: 'approval',
      status: 'esperando_aprobacion',
      sensitive,
      injection: false,
      blocked: false,
    };
  }

  return {
    category,
    confidence,
    draft_reply: draft,
    reasoning,
    route: 'auto',
    status: 'pendiente',
    sensitive: false,
    injection: false,
    blocked: false,
  };
}

const base = $('Preparar bloque').item.json;
const config = $('Configuración').first().json;
let raw = '';
let parsed = null;
if (!$json.error) {
  raw = llmPayload($json);
  parsed = extractJson(raw);
}
const decision = decide({
  subject: base.subject,
  body: base.body,
  injection: base.injection,
  sources: base.sources || [],
  parsed,
}, config);
return { json: { ...base, ...decision, model_raw: String(raw).slice(0, 2000) } };

